using System;
using UnityEngine;

namespace Astrea;

[Serializable]
public class InventoryItem
{
	[HideInInspector]
	public string name;

	public Dice dice;

	public int amount;

	public InventoryItem(Dice dice, int amount)
	{
		name = dice.DiceName.ToLower().Replace(" ", "");
		this.dice = dice;
		this.amount = amount;
	}
}
